# Type I error rate validation: simulate under null hypothesis (equal means)
# to verify that alpha = 0.05 is correctly maintained

set.seed(20250102)

# Parameters: null hypothesis (no group difference)
n_per_group <- 17
null_mean <- 50  # both groups have same mean
marginal_sd <- 2.5
k <- 3
rho <- 0.5
alpha_nominal <- 0.05
num_simulations <- 5000

# Build compound symmetry covariance matrix
sigma_sq <- marginal_sd^2
cov_matrix <- matrix(NA, nrow = k, ncol = k)
for (i in 1:k) {
  for (j in 1:k) {
    if (i == j) {
      cov_matrix[i, j] <- sigma_sq
    } else {
      cov_matrix[i, j] <- rho * sigma_sq
    }
  }
}

cat("=== TYPE I ERROR RATE VALIDATION ===\n")
cat("Testing null hypothesis: both groups have mean", null_mean, "\n")
cat("Simulating", num_simulations, "datasets with n =", n_per_group, "per group\n")
cat("Nominal alpha = 0.05 (two-sided)\n\n")

# Count rejections under null
false_rejections <- 0

for (sim in 1:num_simulations) {
  # Generate data for group 1 (null mean)
  group1_data <- matrix(NA, nrow = n_per_group, ncol = k)
  for (i in 1:n_per_group) {
    group1_data[i, ] <- MASS::mvrnorm(1, mu = rep(null_mean, k), Sigma = cov_matrix)
  }

  # Generate data for group 2 (null mean)
  group2_data <- matrix(NA, nrow = n_per_group, ncol = k)
  for (i in 1:n_per_group) {
    group2_data[i, ] <- MASS::mvrnorm(1, mu = rep(null_mean, k), Sigma = cov_matrix)
  }

  # Compute subject-level averages
  avg_group1 <- rowMeans(group1_data)
  avg_group2 <- rowMeans(group2_data)

  # Perform pooled two-sample t-test
  t_result <- t.test(avg_group1, avg_group2, var.equal = TRUE)

  # Count false rejections
  if (t_result$p.value < alpha_nominal) {
    false_rejections <- false_rejections + 1
  }
}

# Type I error estimate
type1_error <- false_rejections / num_simulations
type1_se <- sqrt(type1_error * (1 - type1_error) / num_simulations)

cat("Results:\n")
cat("False rejections:", false_rejections, "out of", num_simulations, "\n")
cat("Estimated Type I error rate:", type1_error, "\n")
cat("Standard error:", type1_se, "\n")
cat("95% CI: [", type1_error - 1.96*type1_se, ",", type1_error + 1.96*type1_se, "]\n")
cat("Nominal alpha:", alpha_nominal, "\n\n")

cat("=== ASSESSMENT ===\n")
if (abs(type1_error - alpha_nominal) <= 2 * type1_se) {
  cat("✓ Type I error rate is consistent with nominal α = 0.05\n")
  cat("  Test is properly calibrated.\n")
} else {
  cat("⚠ Type I error rate differs from nominal α\n")
}

